import{z as i,x as s,o as l,c as d,q as B,j as n,D as t,d as a,s as r,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"多租户隔离深化","description":"","frontmatter":{"title":"多租户隔离深化","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/sch-multitenant-isolation.md","filePath":"llm/sch-multitenant-isolation.md","lastUpdated":1791063341000}'),D={name:"llm/sch-multitenant-isolation.md"};function m(h,E,p,C,u,c){const A=s("Mermaid");return l(),d("div",null,[E[2]||(E[2]=B('<h1 id="多租户隔离深化" tabindex="-1">多租户隔离深化 <a class="header-anchor" href="#多租户隔离深化" aria-label="Permalink to &quot;多租户隔离深化&quot;">​</a></h1><div class="epigraph"><p>隔离不是把人分开，是把最坏步时延变成常数：一次前向内部的份额，是邻居唯一绕不过的墙。</p><footer>—— 据 Punica 与 S-LoRA（均 MLSys 2024）的多租户形态，按站内三层框架整理</footer></div><p><a href="/llm/sch-autoscaling">上一课</a>管容量；本课回到租户：多个租户共享同一套引擎与池子时，调度器怎么把隔离做成机制而不是口号。性能、故障、机密三层框架主干已有（<a href="/llm/multi-tenant-gpu">多租户隔离</a>）；本课深化第一层——性能隔离的调度实现：配额怎么叠、份额怎么切、怎么验收。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>性能隔离的难点是<strong>二维资源加迭代级共享</strong>。租户 A 的一条 8k prefill 在同一次前向里把所有租户的步时延拉长——批是共享的，伤害也是共享的。A 的长 decode 群把 KV 池占满，B 的新请求进不来，虽然 A 没有超任何「请求数」配额。按请求数配额没用：一条请求的代价差三个数量级（<a href="/llm/token-ratelimit">token 计量与限流</a> 已论证按 token 计）。但按 token 配额也不够：排队占坑的请求不产 token，却实打实占着池子与名额。隔离要同时管住三样：准入速率、占坑规模、步内消耗。</p><h3 id="三道配额叠着用" tabindex="-1">三道配额叠着用 <a class="header-anchor" href="#三道配额叠着用" aria-label="Permalink to &quot;三道配额叠着用&quot;">​</a></h3><p>第一道，<strong>准入</strong>：每租户 TPM 令牌桶（复用限流课的机制），挡速率。<span class="marginnote">术语翻译：令牌桶就是「按固定速率往桶里放代币、每个请求要花掉代币、桶容量有上限」的限速器——平时攒下的代币允许小突发，但长期速率超不过放币速率。TPM 就是「每分钟放多少币」。它挡的是租户发请求的平均火力。</span>第二道，<strong>占坑</strong>：每租户最大运行数与 KV 字节水印，挡驻留；超自己水位的租户先抢自己的请求——「自己抢自己」，抢占课的机制获得租户语义。<span class="marginnote">直觉类比：「自己抢自己」就像电梯超载时先请同一公司的同事下去等下一趟——同一家的请求互相让位，保证隔壁公司的人不被牵连。没有这道，A 家的长 decode 群会把整个电梯（KV 池）占满，B 家连门都进不来。</span>第三道，<strong>步内</strong>：本步 token 预算按租户切份额，加权公平（<a href="/llm/sch-priority-fairness">优先级与公平性</a> 的机制落到租户维）；这是唯一能在一次前向<strong>内部</strong>保护邻居的旋钮，批外两道管不到同批之内。份额是软的：保底下限加突发上限；超卖比例是这层的定价，依据是租户峰值不同相。计费与退款按三本账出：token、卡秒、达标率；账单口径必须与限流口径同源，否则对不上账。</p>',7)),(l(),n(o,null,{default:t(()=>[r(A,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E7%A7%9F%E6%88%B7%E8%AF%B7%E6%B1%82%22%5D%20--%3E%20Q1%5B%22%E5%87%86%E5%85%A5%EF%BC%9A%E6%AF%8F%E7%A7%9F%E6%88%B7%E4%BB%A4%E7%89%8C%E6%A1%B6%22%5D%0A%20%20Q1%20--%3E%20Q2%7B%22%E8%87%AA%E5%B7%B1%20KV%20%E6%B0%B4%E4%BD%8D%E8%B6%8A%E7%BA%BF%22%7D%0A%20%20Q2%20--%3E%7C%E6%98%AF%7C%20SELF%5B%22%E6%8A%A2%E8%87%AA%E5%B7%B1%E7%9A%84%E8%AF%B7%E6%B1%82%EF%BC%9A%E5%85%88%E8%AE%A9%E5%85%88%E5%9B%9E%22%5D%0A%20%20Q2%20--%3E%7C%E5%90%A6%7C%20ADM%5B%22%E8%BF%9B%E7%AD%89%E5%BE%85%E9%98%9F%E5%88%97%22%5D%0A%20%20ADM%20--%3E%20Q3%5B%22%E6%AD%A5%E5%86%85%EF%BC%9A%E6%9C%AC%E6%AD%A5%E9%A2%84%E7%AE%97%E6%8C%89%E7%A7%9F%E6%88%B7%E4%BB%BD%E9%A2%9D%E5%88%87%22%5D%0A%20%20Q3%20--%3E%20ENG%5B%22%E5%BC%95%E6%93%8E%EF%BC%9A%E4%B8%80%E6%AC%A1%E5%89%8D%E5%90%91%22%5D%0A%20%20ENG%20--%3E%20LED%5B%22%E4%B8%89%E6%9C%AC%E8%B4%A6%EF%BC%9Atoken%20%2F%20%E5%8D%A1%E7%A7%92%20%2F%20%E8%BE%BE%E6%A0%87%E7%8E%87%22%5D%0A%20%20LED%20--%3E%20BILL%5B%22%E8%AE%A1%E8%B4%B9%E4%B8%8E%E9%80%80%E6%AC%BE%EF%BC%8C%E4%B8%8E%E9%99%90%E6%B5%81%E5%90%8C%E6%BA%90%22%5D%0A"})]),fallback:t(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"方法",tabindex:"-1"},[a("方法 "),e("a",{class:"header-anchor",href:"#方法","aria-label":'Permalink to "方法"'},"​")],-1)),E[4]||(E[4]=e("p",null,[a("本课的方法是"),e("strong",null,"三道配额叠加加对抗验收"),a("：把「隔离」拆成准入速率、占坑规模、步内消耗三个可分别配置的旋钮——令牌桶挡速率，每租户 KV 水位配「自己抢自己」，步内预算按份额切——三道各管一段伤害路径，缺一道即漏。验收方法是对抗测试：让邻居打满长 prefill 长跑，看本租户分位是否仍在合同内。方法选型的口径先钉死：软隔离只交付性能这一层，机密与故障两层另付更贵的价钱。")],-1)),E[5]||(E[5]=e("p",null,"对抗验收长这样：",-1)),(l(),n(o,null,{default:t(()=>[r(A,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20SET%5B%22%E5%90%8C%E4%B8%80%E5%BC%95%E6%93%8E%E4%B8%8A%E6%94%BE%E7%A7%9F%E6%88%B7%20A%20%E4%B8%8E%20B%22%5D%20--%3E%20FLOOD%5B%22A%20%E6%89%93%E6%BB%A1%EF%BC%9A%E9%95%BF%20prefill%20%E6%8C%81%E7%BB%AD%E7%81%8C%E5%85%A5%22%5D%0A%20%20FLOOD%20--%3E%20MEA%5B%22%E6%B5%8B%20B%EF%BC%9ATPOT%20P99%20%E4%B8%8E%E9%94%99%E8%AF%AF%E7%8E%87%22%5D%0A%20%20MEA%20--%3E%20J%7B%22B%20%E7%9A%84%E5%88%86%E4%BD%8D%E4%BB%8D%E5%9C%A8%E5%90%88%E5%90%8C%E5%86%85%EF%BC%9F%22%7D%0A%20%20J%20--%3E%7C%22%E6%98%AF%22%7C%20PASS%5B%22%E9%9A%94%E7%A6%BB%E6%88%90%E7%AB%8B%22%5D%0A%20%20J%20--%3E%7C%22%E5%90%A6%22%7C%20FAIL%5B%22%E9%9A%94%E7%A6%BB%E6%BC%8F%E6%B0%B4%EF%BC%9A%E5%AE%9A%E4%BD%8D%E6%98%AF%E5%93%AA%E9%81%93%E9%85%8D%E9%A2%9D%E6%B2%A1%E6%8B%A6%E4%BD%8F%22%5D%0A%20%20FAIL%20--%3E%20TUNE%5B%22%E6%94%B6%E7%B4%A7%E5%8D%A0%E5%9D%91%E6%B0%B4%E4%BD%8D%E6%88%96%E6%AD%A5%E5%86%85%E4%BB%BD%E9%A2%9D%22%5D%0A%20%20TUNE%20--%3E%20FLOOD%0A"})]),fallback:t(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=B('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>验收是对抗性的，这是本课最重要的一条机制：让租户 A 打满长 prefill 长跑，测 B 的 TPOT P99 与错误率——通过标准是 B 的分位仍在合同内，而不是 A 礼貌（<a href="/llm/multi-tenant-gpu">多租户隔离</a> 的测试协议）。空载分位在多租户里没有意义：邻居才是分位的主要作者。<span class="marginnote">常见误区：验收隔离时只跑一下空载压测、看分位漂亮就签字。空载时根本没有邻居，分位当然好看；多租户系统里你的尾部延迟主要是邻居写的——A 家一条 8k 前填就能让全楼 ITL 集体跳一截。验收必须让最坏的邻居在场。</span>隔离与利用率是前沿：硬切份额保下限，牺牲峰值共享的收益；份额切得越细，调度税越重。边界要诚实：软隔离挡不住对抗与合规——机密隔离要地址空间与进程边界，故障隔离要切片或多进程，那是三层框架里更贵的两层，本课的调度机制只交付第一层。</p><p><span class="marginnote">一步之内的数字：一条 8k 提示不切块整步执行，邻居的 ITL 直接长出全步时间（毫秒级跳到百毫秒级）；切成 512 token 的块并给单租户步内预算上限后，伤害上界变成一块的时间。隔离的物理含义就是这句话：把最坏步时延从「取决于邻居」变成「取决于配置」。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>租户与适配器一一对应时（<a href="/llm/sch-multi-lora">多 LoRA 的调度</a>），配额自然落到适配器粒度，但驻留池是新的共享地皮，LRU 也要按租户记账。共享前缀树必须按租户分键：跨租户命中是机密事故（<a href="/llm/sch-cache-aware-routing">缓存感知路由</a> 的边界在这里升级为安全条款）。机群层多租户（多引擎副本、多作业）的公平与配额另有专门机制（<a href="/llm/cluster-fair-scheduling">机群公平调度</a>），本课停在单引擎与路由层；两层配额要对齐口径，否则租户在引擎内守约、在网关被拒，或者反过来。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>性能隔离要同时管准入速率、占坑规模、步内消耗；请求数配额无效。</li><li>三道配额：令牌桶、每租户 KV 水位（自己抢自己）、步内预算按份额切。</li><li>步内份额是唯一能在一次前向内部保护邻居的机制。</li><li>验收是对抗性的：邻居打满时自己的分位不破才算隔离成立。</li><li>隔离与利用率是前沿，超卖比例是定价；软隔离只交付性能层。</li><li>出处：多租户形态见 Chen et al.（Punica）与 Sheng et al.（S-LoRA），MLSys 2024；三层框架与对抗测试按站内口径整理。</li></ul>',7))])}const T=i(D,[["render",m]]);export{f as __pageData,T as default};
